(()=>{'use strict';const data=JSON.parse(document.getElementById('catalog-data').textContent),all=data.products,grid=document.querySelector('#real-products'),modal=document.querySelector('#detail'),body=document.querySelector('#detail-body');let filter='all',query='',sort='featured';const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const key=p=>p.url.split('/').pop();let saved;try{saved=JSON.parse(localStorage.getItem('caisik-product-wishlist')||'[]')}catch{saved=[]}if(!Array.isArray(saved))saved=[];function persist(){try{localStorage.setItem('caisik-product-wishlist',JSON.stringify(saved))}catch{}}function realSave(id){saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];persist();render();if(typeof toast==='function')toast('Product wishlist updated in this browser.')}function card(p){const id=key(p);return `<article class="live-product"><a href="${esc(p.url)}" data-real-detail="${esc(id)}"><img loading="lazy" width="800" height="800" src="${esc(p.localImage)}" alt="${esc(p.displayName||p.name)} — actual store product preview"><span class="live-product-arrow">↗</span></a><button class="real-save" data-real-save="${esc(id)}" aria-label="${saved.includes(id)?'Remove':'Save'} ${esc(p.displayName||p.name)}" aria-pressed="${saved.includes(id)}">${saved.includes(id)?'♥':'♡'}</button><div class="live-product-meta"><h3><a href="${esc(p.url)}" data-real-detail="${esc(id)}">${esc(p.displayName||p.name)}</a></h3><span>${esc(p.priceLabel)}</span></div><p>STORE PRICE SNAPSHOT / EUR</p><a class="real-buy" href="${esc(p.url)}">CHOOSE OPTIONS IN STORE ↗</a></article>`}function render(){let list=all.filter(p=>(filter==='all'||filter==='saved'&&saved.includes(key(p))||p.category===filter)&&[p.name,p.displayName].join(' ').toLowerCase().includes(query));if(sort!=='featured')list.sort((a,b)=>{const n=p=>Number(p.priceLabel.replace(/[^0-9.]/g,''));return sort==='price-low'?n(a)-n(b):n(b)-n(a)});grid.innerHTML=list.length?list.map(card).join(''):'<p>No products match. Try another category or clear your search.</p>';document.querySelector('#catalog-count').textContent=`${list.length} / ${all.length} PRODUCTS`;document.querySelector('#real-saved-count').textContent=String(saved.length)}
function detail(p){const opts=p.options?.filter(o=>o.values?.length)||[];const variants=p.variants||[];body.innerHTML=`<div class="real-detail-grid"><div><img class="real-detail-photo" src="${esc(p.localImage)}" alt="${esc(p.displayName||p.name)}"><a class="text-button" href="${esc(p.url)}">VIEW ALL IMAGES IN ORIGINAL STORE ↗</a></div><div><span class="eyebrow">VERIFIED PUBLIC CATALOG / ${data.checkedAt}</span><h2>${esc(p.displayName||p.name)}</h2><strong class="real-detail-price">${esc(p.priceLabel)}</strong>${p.description?`<p>${esc(p.description)}</p>`:''}${opts.map(o=>`<div class="verified-options"><b>${esc(o.title)}</b><p>${o.values.map(v=>`<span>${esc(v)}</span>`).join('')}</p></div>`).join('')}${variants.length?`<details class="variant-details"><summary>VIEW ${variants.length} SOURCE VARIANTS & SKUS</summary><ul>${variants.map(v=>`<li>${esc(v.title)}<small>${esc(v.sku||'SKU not provided')}</small></li>`).join('')}</ul></details>`:''}<p class="fineprint">Price and options were read from the /dk storefront on ${data.checkedAt}. Stock, current price, shipping, tax and delivery must be confirmed in the original store. Images are store/Printful previews; not proof of a photographed physical sample.</p><a class="button" href="${esc(p.url)}">SELECT SIZE & BUY IN STORE ↗</a><button class="text-button" data-real-save="${esc(key(p))}">${saved.includes(key(p))?'REMOVE FROM WISHLIST':'SAVE PRODUCT ♡'}</button></div></div>`;modal.showModal()}
document.addEventListener('click',e=>{const save=e.target.closest('[data-real-save]');if(save){e.preventDefault();realSave(save.dataset.realSave);return}const link=e.target.closest('[data-real-detail]');if(link){const p=all.find(x=>key(x)===link.dataset.realDetail);if(p){e.preventDefault();detail(p)}}});document.querySelectorAll('[data-catalog-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.catalogFilter;document.querySelectorAll('[data-catalog-filter]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))});render()});document.querySelector('#catalog-search').oninput=e=>{query=e.target.value.toLowerCase().trim();render()};document.querySelector('#catalog-sort').onchange=e=>{sort=e.target.value;render()};render();
const previous=document.querySelector('#privacy-open').onclick;document.querySelector('#privacy-open').onclick=()=>{previous();const p=document.createElement('p');p.textContent='Product catalog: verified public snapshot from hiphop.caisik.i234.me /dk (20 products across pages 1–2). Product wishlist also uses browser-local storage. Purchases redirect to that store. Cart, payment and fulfillment have not been tested by this Site.';body.appendChild(p);const b=document.createElement('button');b.className='text-button';b.textContent='CLEAR PRODUCT WISHLIST';b.onclick=()=>{saved=[];persist();render();modal.close()};body.appendChild(b)};
document.addEventListener('caisik-clear-local',()=>{saved=[];persist();render()});
})();
